#[test]
fn unicode_latin_script_results_snapshot() {
    let mut rows = String::new();
    for name in ["Script=Latin", "Script=Latn", "sc=Latin", "sc=Latn"] {
        for body in [
            format!(r"\p{{{name}}}"),
            format!(r"\P{{{name}}}"),
            format!(r"(?<x>[\p{{{name}}}K])"),
        ] {
            let pattern = JsString::from(body.as_str());
            for flags in ["dug", "diug", "divg", "divy"] {
                for input in ["KaμΣς😀\u{378}\n", "X\r\nA\u{2028}𐞀", ""] {
                    let input = JsString::from(input);
                    for start in [0, 1, 3] {
                        let script = format!(
                            "let r=new RegExp({pattern:?},{flags:?});r.lastIndex={start};let m=r.exec({input:?});JSON.stringify({{m,index:m?.index,groups:m?.groups,indices:m?.indices,indexGroups:m?.indices?.groups,lastIndex:r.lastIndex,source:r.source}})"
                        );
                        let Value::String(result) = Realm::default().eval(&script).unwrap() else {
                            panic!("{script}")
                        };
                        writeln!(
                            rows,
                            "{body:?} flags={flags:?} input={input:?} lastIndex={start} {result:?}"
                        )
                        .unwrap();
                    }
                }
            }
        }
    }
    insta::assert_snapshot!(rows);
}

#[test]
fn unicode_latin_script_captures_context_and_pair_starts() {
    for mode in ["u", "v"] {
        check(&format!(
            r"let r=/^(?<x>([\p{{sc=Latn}}K]))$/dim{mode}g,m=r.exec('μ\r\nK\u2028');m.index===3&&m[1]==='K'&&m[2]==='K'&&m.indices.groups.x===m.indices[1]&&m.indices[2][1]===4&&r.lastIndex===4"
        ));
        check(&format!(
            r"let r=/(?<__proto__>\p{{Script=Latin}})/d{mode}y;r.lastIndex=1;let m=r.exec('𐞀A');m.index===0&&m[1]==='𐞀'&&m.indices[1][1]===2&&r.lastIndex===2&&Object.getPrototypeOf(m.groups)===null&&m.indices.groups.__proto__===m.indices[1]"
        ));
        check(&format!(
            r"let r=/\P{{sc=Latin}}/d{mode}g;r.lastIndex=1;let m=r.exec('𐞀\uD800');m.index===2&&m[0]==='\uD800'&&r.lastIndex===3"
        ));
        check(&format!(
            r"let r=/\P{{Script=Latn}}/{mode}y;r.lastIndex=1;r.exec('𐞀\uD800')===null&&r.lastIndex===0"
        ));
    }
}

#[test]
fn unicode_latin_script_consumers_preserve_original_text() {
    for mode in ["u", "v"] {
        check(&format!(
            r"let a=[...'A😀μB'.matchAll(/(?<x>\P{{sc=Latin}})/d{mode}g)];a.length===2&&a[0][1]==='😀'&&a[0].index===1&&a[0].indices[1][1]===3&&a[1][1]==='μ'&&a[1].index===3"
        ));
        check(&format!(
            r"'ABμ'.replace(/(?<x>\p{{sc=Latn}})/{mode}g,'<$1:$<x>>')==='<A:A><B:B>μ'"
        ));
        check(&format!(
            r"'μABμ'.split(/(\p{{Script=Latin}})/{mode}).join('|')==='μ|A||B|μ'&&'μ😀A'.search(/\p{{sc=Latn}}/{mode})===3&&'ABμ'.match(/\p{{Script=Latn}}/{mode}g).join('')==='AB'"
        ));
        check(&format!(
            r"let t='',x='ABμA'.replace(/(\p{{sc=Latin}})/{mode}g,(m,c,p)=>{{t+=p;return '_'}});x==='__μ_'&&t==='013'"
        ));
    }
}

#[test]
fn unicode_latin_script_clones_coercions_and_strict_writes() {
    check(
        r"let r=/^(?<x>\p{sc=Latn})$/dmu,c=new RegExp(r,'divy');c.source==='^(?<x>\\p{sc=Latn})$'&&c.unicodeSets&&!c.unicode&&!c.multiline&&c.exec('a').groups.x==='a'&&c.lastIndex===1",
    );
    check(
        r"let t='',r=/\p{Script=Latin}/uy;r.lastIndex={valueOf(){t+='i';return 1}};let m=r.exec({toString(){t+='s';return '𐞀'}});t==='si'&&m[0]==='𐞀'&&m.index===0&&r.lastIndex===2",
    );
    check(
        r"let r=/\p{sc=Latin}/vy;Object.defineProperty(r,'lastIndex',{writable:false});let caught=false;try{r.exec('A')}catch(e){caught=e instanceof TypeError}caught&&r.lastIndex===0",
    );
    check(
        r"let r=/\P{Script=Latn}/vy;r.lastIndex=1;Object.defineProperty(r,'lastIndex',{writable:false});let caught=false;try{r.exec('𐞀\uD800')}catch(e){caught=e instanceof TypeError}caught&&r.lastIndex===1",
    );
}

#[test]
fn unicode_latin_script_opted_work_and_remaining_sets() {
    let mut realm = Realm::new(Limits {
        max_steps: Some(30000),
        ..Limits::default()
    });
    realm
        .eval("let r=/\\p{Script=Latin}/ug,marker=0,text='μ'.repeat(10000);r.lastIndex=1")
        .unwrap();
    assert!(matches!(
        realm.eval("try{r.exec(text)}catch{marker=1}finally{marker=2}"),
        Err(Error::Limit { .. })
    ));
    assert_eq!(
        realm.eval("marker===0&&r.lastIndex===1"),
        Ok(Value::Boolean(true))
    );
    check(
        r#"let m=/\p{Script_Extensions=Latin}/u.exec('A');JSON.stringify(m)==='["A"]'&&m.index===0&&m.input==='A'"#,
    );
    check(
        r"let m=/[\p{sc=Latn}&&A]/v.exec('A');m!==null&&m.length===1&&m[0]==='A'&&m.index===0&&m.input==='A'",
    );
    check(r"/[\p{sc=Latn}--A]/v.exec('A')===null");
    check(
        r"let s=String.fromCodePoint(0x61),m=/[\p{sc=Latn}--A]/v.exec(s);m!==null&&m.length===1&&m[0]===s&&m.index===0&&m.input===s",
    );
    for source in [
        r"/\p{sc=Latn}+b/u.exec('AA')",
        r"/\p{sc=Latn}A/v.exec('AA')",
    ] {
        assert!(
            crate::common::regexp_oracle::check(&mut Realm::default(), source),
            "{source}"
        );
    }
}

#[test]
fn unicode_latin_script_repetitions_retain_last_capture_and_outside_words() {
    for mode in ["u", "v"] {
        check(&format!(
            r"let r=/\B(?<x>\p{{sc=Latn}})+\B/d{mode}g,m=r.exec('μ𐞀𐞀𐞀μ');m.index===1&&m[0]==='𐞀𐞀𐞀'&&m.groups.x==='𐞀'&&m.indices.groups.x[0]===5&&m.indices.groups.x[1]===7&&r.lastIndex===7"
        ));
    }
}

#[test]
fn unicode_latin_script_former_direct_eval_context_executes_normally() {
    check(r"(/([\p{Script=Latin}])/iu.exec('a'))!==null");
    check(r"(/(\p{Script=Latin})(.)/v.exec('Aa'))!==null");
    check(r"(/[\p{Script=Latin}]/iv.exec('a'))!==null");
    check(r"(/[\p{Script=Latin}]/u.exec('A'))!==null");
    check(r"(/[\p{Script=Latin}]/u.exec('a'))!==null");
    check(r"(/[\p{Script=Latin}]/v.exec('a'))!==null");
    check(r"(/\b[\p{Script=Latin}]\b/vi.exec('A'))!==null");
    check(r"(/\b\p{Script=Latin}\b/vi.exec('A'))!==null");
    check(r"(/\p{Script=Latin}+/vi.exec('AA'))!==null");
    check(r"(/\p{Script=Latin}/iv.exec('a'))!==null");
    check(r"(/\p{Script=Latin}/u.exec('A'))!==null");
    check(r"(/\p{Script=Latin}/u.exec('a'))!==null");
    check(r"(/^(\p{Script=Latin})$/u.exec('A'))!==null");
    check(r"(/^[\p{Script=Latin}]$/u.exec('a'))!==null");
    check(r"(/^\p{Script=Latin}$/v.exec('a'))!==null");
    check(r"(/^\p{Script=Latin}+/vi.exec('AA'))!==null");
    check(
        r#"let marker=0,result;try{result=eval("marker=1; /\\p{Script=Latin}/u.test('a');")}catch{marker=2}finally{marker=3}marker===3&&result===true"#,
    );
}
